class _Outcome(Exception):
    """内部使用：一次动作的失败分类，不会逃出 :func:`apply_transaction`。"""

    def __init__(self, message, action=None, cause=None):
        self.message = message
        self.action = action
        self.cause = cause
        super().__init__(message)


class _Deferred(_Outcome):
    """目标被别的进程占用：推迟到下一次执行，本次事务继续。"""


class _Fatal(_Outcome):
    """无法推迟的失败：本次事务必须整体回滚。"""


def _remove_quietly(path):
    try:
        os.remove(path)
    except OSError:
        pass


def _read_bytes(path):
    try:
        with open(path, "rb") as handle:
            return handle.read()
    except OSError:
        return None


def _ensure_parent(path):
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)


def _is_locked(exc):
    """``exc`` 是否属于「文件被别的进程占用」这类**可以推迟**的失败。"""
    if isinstance(exc, (FileNotFoundError, NotADirectoryError, IsADirectoryError,
