        return False
    if isinstance(exc, PermissionError):
        return True
    if not isinstance(exc, OSError):
        return False
    if getattr(exc, "winerror", None) in _LOCKED_WINERRORS:
        return True
    if exc.errno in _STRUCTURAL_ERRNOS:
        return False
