    # 变体）都按「占用」处理：推迟一次，总比毁掉整次安装好。
    return True


def _classify(exc, target):
    """把一个 :class:`OSError` 归类成可推迟或不可推迟的失败。"""
    message = "%s: %s" % (target, exc)
    if _is_locked(exc):
        return _Deferred(message, cause=exc)
    return _Fatal(message, cause=exc)


