    """把 ``source`` 放到 ``destination``。

    失败时目标保持原样：要么根本没被碰过（占用），要么由调用方回滚。
    """
    if os.path.isdir(destination):
        # 目标位置被同名目录占据，替换永远不会成功，也就无从推迟。
        raise _Fatal("destination is occupied by a directory: %s" % (destination,))
    if os.path.isfile(destination) and not os.access(destination, os.W_OK):
        # 只读的目标文件在 Windows 上同样替换不掉，只能推迟。
        raise _Deferred("destination is not writable: %s" % (destination,))
