    for path in reversed(created or ()):
        try:
            os.rmdir(path)
        except OSError:
            pass


def _force_rmtree(path):
    """删掉一棵目录树，连只读文件一起。

    快照可能是从只读的载荷文件复制来的；Windows 上那样的文件
    直接 rmtree 会失败，得先把只读位清掉。
    """
    if not path:
        return
    for base, dirs, names in os.walk(path, topdown=False):
        for name in names:
            target = os.path.join(base, name)
            try:
                os.chmod(target, 0o666)
            except OSError:
                pass
            _remove_quietly(target)
        for name in dirs:
            try:
                os.rmdir(os.path.join(base, name))
            except OSError:
                pass
    try:
        os.rmdir(path)
    except OSError:
        pass


def _is_locked(exc):
    """``exc`` 是否属于「文件被别的进程占用」这类**可以推迟**的失败。"""
    if isinstance(exc, (FileNotFoundError, NotADirectoryError, IsADirectoryError,
                        FileExistsError)):
        return False
    if isinstance(exc, PermissionError):
        return True
    if not isinstance(exc, OSError):
        return False
    if getattr(exc, "winerror", None) in _LOCKED_WINERRORS:
        return True
    if exc.errno in _STRUCTURAL_ERRNOS:
        return F
